const $ = (s, root = document) => root.querySelector(s);
const app = $('#app');
const API_BASE = '/api/kitchen/rooms';
const shareUrl = (role, roomPin=pin) => `${location.origin}/?battle=7&${role}=${encodeURIComponent(roomPin)}`;
let retryDelay = 3000;
function syncParentRoute(){if(window.parent!==window)window.parent.postMessage({type:'crazy-kitchen:navigate',search:location.search},location.origin);}
const INGREDIENTS = {Bread:'🍞',Egg:'🥚',Cheese:'🧀',Tomato:'🍅',Chicken:'🍗',Mushroom:'🍄',Milk:'🥛',Chocolate:'🍫',Fruit:'🍓',Rice:'🍚'};
const TEAM_ICONS = ['🍅','🥑','🍋','🍇','🥕','🫐','🌽','🍒','🥦','🍊'];
const FORMAT = {typed_correction:'Fix the sentence',multiple_choice:'Pick the best answer',sentence_rebuild:'Build the sentence'};
const STATUS = {waiting:'Waiting',submitted:'Submitted',accepted:'Accepted',rejected:'Rejected'};
let mode = 'home', pin = '', token = '', state = null, pending = null, lastAttempt = 0, clockOffset = 0;
let routeGeneration=0, pollInFlight=null, actionInFlight=null, joinInFlight=null, pendingJoin=null, joinLastAttempt=0, joinRetryDelay=3000;
const ui = {error:'',notice:'',online:navigator.onLine,loading:false,busy:false,review:false,tab:'play',selected:[],wordOrder:[],answer:'',questionId:null,modal:null,slot:0,teamName:'',form:{teamCount:'10',roomName:'Crazy Kitchen'},signature:''};
const memory = new Map();
const storage = {get(key){try{return localStorage.getItem(key) ?? memory.get(key);}catch{return memory.get(key);}},set(key,value){memory.set(key,value);try{localStorage.setItem(key,value);}catch{}},remove(key){memory.delete(key);try{localStorage.removeItem(key);}catch{}}};
const session = {get(key){try{return sessionStorage.getItem(key) ?? memory.get(key);}catch{return memory.get(key);}},set(key,value){memory.set(key,value);try{sessionStorage.setItem(key,value);}catch{}}};
const STUDENT_ROUTE_KEY='grammartest_student_route';
function studentRoute(){try{const route=JSON.parse(session.get(STUDENT_ROUTE_KEY)||'null');return route?.battle===7&&typeof route.room==='string'&&(!route.room||/^\d{5}$/.test(route.room))?route:null;}catch{return null;}}
function rememberStudent(room){session.set(STUDENT_ROUTE_KEY,JSON.stringify({battle:7,room}));}
function replaceRoute(search){if(history.replaceState)history.replaceState({},'',`./index.html${search}`);syncParentRoute();}
const credentialKey = () => `crazy-kitchen:${mode === 'host' ? 'host' : 'team'}:${pin}`;
const pendingKey = () => `crazy-kitchen:pending:${mode}:${pin}`;
const pendingJoinKey = (roomPin=pin) => `crazy-kitchen:pending-join:${roomPin}`;
function readPendingJoin(roomPin){try{const value=JSON.parse(storage.get(pendingJoinKey(roomPin)) || 'null');return value&&value.pin===roomPin&&/^\d{5}$/.test(value.pin)&&/^[-a-zA-Z0-9]{20,100}$/.test(value.clientId)&&Number.isInteger(value.teamSlot)&&value.teamSlot>=1&&value.teamSlot<=10&&typeof value.name==='string'&&value.name.trim().length>0&&value.name.length<=28?value:null;}catch{return null;}}
const esc = (s) => String(s ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid = () => globalThis.crypto?.randomUUID?.() || `${Date.now()}-${Math.random().toString(36).slice(2)}-${Math.random().toString(36).slice(2)}`;
const icon = (slot) => TEAM_ICONS[((slot || 1)-1)%TEAM_ICONS.length];
const disabled = (condition) => condition ? ' disabled' : '';
const totalStock = (inventory = {}) => Object.values(inventory).reduce((a,b)=>a+Number(b || 0),0);
const rewardItems = (submission = {}) => Array.isArray(submission?.rewards)&&submission.rewards.length?submission.rewards:submission?.reward?[submission.reward]:[];
const rewardPair = (submission) => rewardItems(submission).map((item,index)=>`<span class="reward-item reward-item-${index+1}">${INGREDIENTS[item] || '🥣'} <b>+1 ${esc(item)}</b></span>`).join('');
const phaseLabel = () => ({lobby:'Prep time',question:'On the menu',reveal:'The answer is in',rush:state?.rushEnded?'Service complete':state?.questionNumber===20?'Last orders!':'Cooking time',finished:'Service complete',closed:'Kitchen closed'}[state?.phase] || 'Ready, chef?');
const remaining = () => Math.max(0,Math.ceil(((state?.rushEndsAt || 0) - Date.now() - clockOffset)/1000));
const answerRemaining = () => state?.answerCountdownEndsAt?Math.max(0,Math.ceil((state.answerCountdownEndsAt-Date.now()-clockOffset)/1000)):null;
const answerTimeUp = () => state?.phase==='question'&&state?.answerCountdownEndsAt&&answerRemaining()===0;
const cookingActive = () => Boolean(state && (state.cookingAvailable ?? ['question','reveal','rush'].includes(state.phase)));
const rushActive = cookingActive; // Legacy saved rooms use the same untimed cooking controls.
const brand = (compact=false) => `<span class="brand ${compact?'compact':''}" aria-label="Crazy Kitchen"><span class="brand-mark" aria-hidden="true">🍳</span><span>crazy<span class="brand-second">kitchen<span class="brand-dot">.</span></span></span></span>`;
const connection = () => `<span class="connection ${ui.online?'':'is-offline'}"><i></i><span>${ui.online?'Live kitchen':'Reconnecting…'}</span></span>`;
const btn = (label,action,cls='button',extra='') => `<button type="button" class="${cls}" data-action="${action}" ${extra}>${label}</button>`;
function announce(text){$('#announcer').textContent=text;}
function setNotice(text){ui.notice=text;announce(text);setTimeout(()=>{if(ui.notice===text){ui.notice='';render();}},5000);}
function render(){
  const reviewScroll=$('.review-list')?.scrollTop || 0, modalScroll=$('.modal-card')?.scrollTop || 0;const active=document.activeElement,focusData=active?.dataset?.action?{...active.dataset}:null,focusId=active?.id,selection=active && ['TEXTAREA','INPUT'].includes(active.tagName)?[active.selectionStart,active.selectionEnd]:null;
  document.body.dataset.role=mode;document.body.dataset.embedded=window.parent!==window?'true':'false';
  app.innerHTML = `${mode==='home'?home():mode==='student'?studentEntry():mode==='join'&&pendingJoin?joinRecoveryView():!state?loadingView():state.phase==='closed'?closedView():mode==='host'?!token?missingHost():host():mode==='screen'?projector():state.me?pupil():joinView()}${feedback()}${dishNotice()}${modal()}`;
  if(focusId){const next=document.getElementById(focusId);if(next){next.focus({preventScroll:true});try{if(selection)next.setSelectionRange(...selection);}catch{}}}
  if($('.review-list'))$('.review-list').scrollTop=reviewScroll;if($('.modal-card'))$('.modal-card').scrollTop=modalScroll;if(!focusId&&focusData){const next=[...document.querySelectorAll('[data-action]')].find(el=>Object.entries(focusData).every(([key,value])=>el.dataset[key]===value));if(next&&!next.disabled)next.focus({preventScroll:true});}
  updateTimers();
}
function feedback(){return `${ui.error?`<div class="toast error" role="alert"><span>${esc(ui.error)}</span>${btn('×','clear-error','icon-button','aria-label="Dismiss error"')}</div>`:''}${ui.notice?`<div class="toast" role="status"><span>${esc(ui.notice)}</span>${btn('×','clear-notice','icon-button','aria-label="Dismiss message"')}</div>`:''}${pending?`<div class="pending-strip" role="status"><span class="spinner"></span><span>${ui.online?'Confirming your action…':'Action not confirmed. Reconnecting and retrying safely…'}</span>${btn('Retry now','retry','text-button')}</div>`:''}`;}
function home(){return `<div class="site-shell"><header class="site-header">${brand()}${connection()}</header><main id="main" class="center-state"><span class="loading-pan">🍳</span><h1>${ui.error?'Your kitchen could not open.':'Opening Battle 7…'}</h1><p>${ui.error?'Check your connection, then try again.':'Preparing your board, team stations and QR code.'}</p>${ui.error?btn('Try again','open-kitchen','button green'):''}</main></div>`;}
function studentEntry(){return `<div class="site-shell narrow"><header class="site-header">${brand()}<span class="role-tag">Student</span></header><main id="main" class="center-state"><h1>Join your kitchen.</h1><p>Scan your teacher’s QR code or enter the new room PIN.</p><form id="pin-form"><div class="field"><label for="join-pin">Room PIN</label><input id="join-pin" name="pin" inputmode="numeric" pattern="[0-9]{5}" maxlength="5" required autocomplete="off"></div><button class="button green" type="submit">Join the kitchen →</button></form><p>Your teacher opens the game on the classroom screen.</p></main></div>`;}
function loadingView(){return `<div class="site-shell"><header class="site-header">${brand()}${connection()}</header><main id="main" class="center-state"><span class="loading-pan" aria-hidden="true">🍳</span><h1>${ui.error?'Let’s get you connected.':'Finding your kitchen…'}</h1><p>${ui.error?'Check the room PIN and your connection, then try again.':'Your place is saved on this device.'}</p>${ui.error?`${btn('Try again','reload','button green')} ${mode==='host'?btn('Open a new kitchen','replace-kitchen','button secondary'):mode==='join'?btn('Enter another PIN','student-entry','button secondary'):''}`:''}</main></div>`;}
function missingHost(){return `<main id="main" class="center-state">${brand()}<span class="big-symbol">🔒</span><h1>This is the teacher’s desk.</h1><p>Open this room on the browser where you created it. The private teacher key stays on that device.</p><a class="button green" href="${esc(shareUrl('screen'))}" target="_blank" rel="noopener">Open public projector</a>${btn('Open a new teacher kitchen','replace-kitchen','text-button')}</main>`;}
function closedView(){if(mode==='join'&&state.me)return `${appHeader('team')}<main id="main" class="phone-shell"><section class="phone-wait"><h1>The teacher ended this game.</h1><p>Your team’s final results are saved below. Stay here or scan the teacher’s next QR code.</p></section>${finalStage()}<div class="personal-total"><span>${esc(state.me.name)} earned</span><strong>${state.me.stars} ★</strong><p>${state.me.recipes?.length||0} recipes discovered</p></div>${leaderboard()}${btn('Join a new student room','student-entry','button green wide')}</main>`;return `<main id="main" class="center-state">${brand()}<span class="big-symbol">👋</span><h1>The kitchen is closed.</h1><p>${mode==='host'?'This room has ended. Your teams keep their results on their phones.':'Ask your teacher for a new room PIN to play again.'}</p>${mode==='host'?btn('Open a new kitchen','new-kitchen','button green'):mode==='join'?btn('Enter a new student PIN','student-entry','button green'):''}</main>`;}
function appHeader(role){return `<header class="game-header"><div class="header-brand">${brand(true)}${role==='host'?'<a class="all-battles text-link" href="/" target="_top">All battles ↗</a>':''}<span class="role-tag">${role==='host'?'Teacher’s desk':role==='screen'?'Classroom screen':esc(state.me?.name || 'Join your team')}</span></div><div class="header-right">${connection()}${role!=='team'?`<span class="room-chip">ROOM <b>${esc(pin)}</b></span>`:`<span class="star-total"><span>★</span> ${state.me?.stars || 0}</span>`}${role==='host'?btn('End room','end-confirm','text-button subtle'):role==='screen'?btn('⛶','fullscreen','icon-button','aria-label="Toggle fullscreen"'):''}</div></header>`;}
function progress(){const q=state.questionNumber || 0;return `<div class="round-progress" aria-label="Question ${q} of ${state.totalQuestions || 20}"><span>${state.phase==='lobby'?'The kitchen is warming up':`Question ${q} of ${state.totalQuestions || 20}`}</span><div class="round-dots">${Array.from({length:20},(_,i)=>`<i class="${i<q?'done':''} ${i===q-1?'current':''} " title="Question ${i+1}"></i>`).join('')}</div><span>Cook anytime · exactly 3 ingredients</span></div>`;}
function host(){return `${appHeader('host')}<main id="main" class="host-layout"><div class="host-main"><section class="desk-heading"><div><span class="eyebrow">WELCOME TO YOUR</span><h1>${esc(state.roomName)}</h1></div>${btn('End game','end-confirm','button secondary small')}<a class="button secondary small" href="${esc(shareUrl('screen'))}" target="_blank" rel="noopener">Open projector <span>↗</span></a></section><div class="privacy-note"><span>🔒</span> Your review panel contains private answers. Share the separate projector window with the class.</div>${progress()}${state.phase==='lobby'?joinDetails(true):kitchenScene('host')}${state.phase==='finished'?finalStage('host'):''}<section class="leaderboard-section"><div class="section-title"><div><span class="eyebrow">THE COMPETITION</span><h2>Kitchen leaderboard</h2></div><span class="muted">${state.teams.filter(t=>t.online).length} teams online</span></div>${leaderboard()}</section>${activity()}</div>${reviewPanel()}</main>`;}
function prompt(question){return (question?.promptSegments || [{text:question?.prompt || '',bold:false}]).map(s=>s.bold?`<strong>${esc(s.text)}</strong>`:esc(s.text)).join('');}
function answerCountdown(context='board'){if(state?.phase!=='question'||!state.answerCountdownEndsAt)return'';const seconds=answerRemaining();return `<div class="answer-countdown ${context} ${seconds<=3?'urgent':''} ${seconds===0?'ended':''}" role="status" aria-live="polite"><span>${seconds===0?"TIME'S UP":'TIME LEFT'}</span><strong data-answer-timer>${String(seconds).padStart(2,'0')}</strong><small>${seconds===0?'Answers are locked. The teacher can review now.':'Keep answering — phones stay active.'}</small></div>`;}
function questionStage(){const q=state.question; if(!q)return `<section class="stage question-stage"><h2>Preparing your next question…</h2></section>`;return `<section class="stage question-stage ${state.phase==='reveal'?'is-revealed':''}">${answerCountdown('board')}<div class="question-topline"><span class="pill">${esc(FORMAT[q.format] || 'English challenge')}</span><span class="question-index">${String(state.questionNumber).padStart(2,'0')} <span>/ 20</span></span></div><p class="question-instruction">${esc(q.instruction)}</p><h2 class="question-prompt">${prompt(q)}</h2>${q.format==='multiple_choice'?`<div class="display-options">${(q.options || []).map((o,i)=>`<div><span>${String.fromCharCode(65+i)}</span>${esc(o.text)}</div>`).join('')}</div>`:''}${q.format==='sentence_rebuild'?`<div class="display-tokens">${(q.tokens || []).map(t=>`<span>${esc(typeof t==='string'?t:t.text)}</span>`).join('')}</div>`:''}${state.phase==='reveal'&&state.answerReveal?`<div class="answer-reveal"><span class="eyebrow">✓ THE ANSWER IS IN</span><h3>${esc(state.answerReveal.canonicalAnswer)}</h3><p>${esc(state.answerReveal.feedback?.explanation || '')}</p></div>`:`<div class="question-foot"><span><i class="live-dot"></i> Every team answers at the same time</span><span>${state.teams.filter(t=>t.submissionStatus!=='waiting').length} / ${state.teams.length} submitted</span></div>`}</section>`;}
function recentCooks(){const cooks=[...(state.latestCooks || [])].reverse().slice(0,5);return `<div class="recent-cooks"><div class="recent-label"><i class="live-dot"></i> FRESH FROM THE KITCHEN</div>${cooks.length?`<div class="cook-feed">${cooks.map(c=>`<article class="cook-item ${c.dish?.type==='basic'?'basic-dish':''}"><span class="dish-icon">${esc(c.dish?.emoji || '🍽️')}</span><div><b>${esc(c.dish?.name || 'Mystery dish')}</b><small>${esc(c.teamName)}</small></div><span class="cook-stars">${Number(c.starsEarned)>0?`+${c.starsEarned} ★`:c.dish?.type==='steal'?'🕵️':c.dish?.type==='steal-star'?'⭐ POWER':'0 ★'}</span>${c.discoveryBonus?'<span class="discovery-dot" title="First discovery bonus">✦</span>':''}</article>`).join('')}</div>`:`<div class="empty-feed">The pass is clear. Who will plate up first?</div>`}</div>`;}
function leaderboard(){return `<div class="leaderboard">${[...state.teams].sort((a,b)=>b.stars-a.stars||(b.acceptedCount||0)-(a.acceptedCount||0)||a.slot-b.slot).map((t,i)=>`<article class="team-card team-color-${(t.slot-1)%5}"><div class="team-card-top"><span class="team-avatar">${icon(t.slot)}</span><span class="place">${i===0&&t.stars>0?'♛':String(i+1).padStart(2,'0')}</span></div><h3>${esc(t.name)}</h3><div class="team-card-bottom"><strong>${t.stars}<span> ★</span></strong><span>${t.inventoryCount} ingredients<br>${t.acceptedCount || 0} accepted</span></div></article>`).join('')}</div>`;}
function reviewPanel(){const submissions=(state.submissions || []).filter(s=>s.status!=='waiting'), unreviewed=submissions.filter(s=>s.status==='submitted').length, joined=state.takenSlots?.length ?? state.teams.length;return `<aside class="review-panel" aria-label="Teacher controls and answer review"><div class="panel-top"><span class="eyebrow">TEACHER’S DESK</span><span class="lock-icon">🔒</span><h2>${phaseLabel()}</h2></div><div class="control-block">${hostControl(unreviewed,joined)}</div>${['question','reveal'].includes(state.phase)?`<div class="sidebar-challenge">${questionStage('host')}</div>`:''}${cookingActive()?'<p class="desk-tip">Teams can cook any time on their phones. Continue reviewing and teaching.</p>':''}<div class="response-heading"><h3>Team response status</h3><span>${submissions.length}/${state.teams.length}</span></div><div class="status-list">${state.teams.length?state.teams.map(t=>`<div class="status-row"><div class="status-team"><span class="mini-avatar">${icon(t.slot)}</span><div><b>${esc(t.name)}</b><small><i class="online-dot ${t.online?'online':''}"></i> ${t.online?'Connected':'Reconnecting'}</small></div></div><span class="status-badge ${esc(t.submissionStatus)}">${esc(STATUS[t.submissionStatus] || 'Waiting')}</span></div>`).join(''):'<p class="empty-roster">Your teams will appear here when they join.</p>'}</div>${['question','reveal'].includes(state.phase)?`<div class="review-toggle">${btn(`Review answers <span>${submissions.length}</span>`, 'toggle-review','button green wide',disabled(ui.busy))}<p class="tiny muted">Open review whenever you choose. Teams without an answer can be marked wrong.</p></div>`:''}<div class="desk-tip"><span>✦</span><p>${state.phase==='lobby'?'Start when your teams have joined. They begin with empty pantries and zero stars.':state.phase==='question'?'An accepted answer earns exactly two independently drawn ingredients. Decisions can change until reveal unless either awarded ingredient has already been used.':state.phase==='rush'?'Cooking is optional. Every ordinary dish earns at least one star.':'You decide when the next round begins.'}</p></div></aside>`;}
function answerReviewModal(){const submissions=(state.submissions || []).filter(s=>s.status!=='waiting'),answered=submissions.filter(s=>!s.unanswered&&s.answer).length;return `<div class="modal-backdrop review-backdrop"><section class="modal-card review-dialog" role="dialog" aria-modal="true" aria-labelledby="review-title"><header class="review-modal-heading"><div><span class="eyebrow">TEACHER ONLY</span><h2 id="review-title">Review team answers</h2><p>${answered} of ${state.teams.length} teams answered</p></div>${btn('×','toggle-review','icon-button','aria-label="Close answer review"')}</header><div class="answer-key"><span class="eyebrow">PRIVATE ANSWER KEY</span><h4>${esc(state.answerKey?.canonicalAnswer || 'Key unavailable')}</h4>${state.answerKey?.acceptedVariants?.length?`<p><b>Also accept:</b> ${esc(state.answerKey.acceptedVariants.join(' / '))}</p>`:''}<p>${esc(state.answerKey?.feedback?.explanation || '')}</p></div><div class="review-list">${state.teams.map(t=>{const answer=(state.submissions || []).find(x=>x.teamId===t.id),s=answer?.status!=='waiting'?answer:null,rewards=rewardItems(s),missing=!s||s.unanswered;return `<article class="review-team"><div class="review-team-head"><b>${icon(t.slot)} ${esc(t.name)}</b><span class="status-badge ${esc(s?.status || 'waiting')}">${esc(s?.unanswered?'No answer':STATUS[s?.status] || 'Waiting')}</span></div><div class="submitted-answer">${missing?'<em>No answer submitted.</em>':esc(s.answer)}${rewards.length?`<div class="reward-line reward-pair">${rewardPair(s)}</div>`:''}</div><div class="judge-actions">${btn('✓ Accept','accept',`judge accept ${s?.status==='accepted'?'selected':''}`,`data-team="${esc(t.id)}"${disabled(missing || ui.busy || state.phase!=='question')}`)}${btn('× Mark wrong','reject',`judge reject ${s?.status==='rejected'?'selected':''}`,`data-team="${esc(t.id)}"${disabled(ui.busy || state.phase!=='question'||s?.rewardLocked)}`)}${s?.rewardLocked?'<small class="tiny muted">One or both ingredients were already used. This accepted reward is locked.</small>':''}</div></article>`;}).join('')}</div><footer class="review-modal-footer"><p>You may review at any time. Mark a team wrong if it did not answer. Each accepted answer awards two ingredients exactly once.</p>${btn('Done','toggle-review','button green')}</footer></section></div>`;}
function hostControl(unreviewed,joined){switch(state.phase){case'lobby':return `<div class="field"><label for="lobby-team-count">Team stations</label><select id="lobby-team-count"${disabled(ui.busy)}>${Array.from({length:9},(_,i)=>i+2).map(n=>`<option value="${n}" ${n===state.teamCount?'selected':''}>${n} teams</option>`).join('')}</select></div><p><b>${joined} of ${state.teamCount}</b> teams have joined.</p>${btn('Start Battle 7 →','start','button coral wide',disabled(ui.busy||joined<state.teamCount))}<p class="tiny muted">One phone per team. All stations need to join before you start.</p>`;case'question':{const seconds=answerRemaining(),started=Boolean(state.answerCountdownEndsAt);return `<p><b>${unreviewed}</b> answer${unreviewed===1?'':'s'} to review</p>${btn(!started?'⏱ Start 10-second countdown':seconds>0?`⏱ ${seconds} seconds left`:'⏱ Time’s up','start-countdown','button secondary wide',disabled(ui.busy||started))}${btn('Reveal answer →','reveal','button coral wide',disabled(ui.busy||unreviewed>0))}<p class="tiny muted">Students can keep typing during the countdown. At zero, unanswered teams can be marked wrong in Review Answers.</p>`;}case'reveal':case'rush':return `<p>${state.questionNumber===20?'Final answer revealed. Let teams finish their dishes, then show the results.':'Ready for the next question? Cooking stays open on team phones.'}</p>${btn(state.questionNumber===20?'Show final results ★':'Next question →','advance','button coral wide',disabled(ui.busy))}`;case'finished':return `<p>Results stay on the teams’ phones.</p>${btn('Open a new kitchen','new-kitchen','button coral wide')}`;default:return'';}}
function activity(){return `<section class="activity-section"><div class="section-title"><h2>Kitchen chatter</h2><span class="eyebrow">RECENT ACTIVITY</span></div><div class="activity-list">${[...(state.events || [])].reverse().slice(0,5).map(e=>`<p><span>✦</span>${esc(e.text)}</p>`).join('')||'<p><span>✦</span>A new kitchen. A fresh start. Let’s see what happens.</p>'}</div></section>`;}
function kitchenScene(role){return `<section class="kitchen-scene" aria-label="Crazy Kitchen classroom board"><img src="./assets/kitchen-hero.png" alt="The Crazy Kitchen chef tossing fresh ingredients over a lively stove"><div class="scene-label"><span class="live-dot"></span>${state.phase==='lobby'?'PREPARING FOR SERVICE':state.phase==='rush'?(rushActive()?'THE KITCHEN IS OPEN':'PANS DOWN, CHEFS'):state.phase==='finished'?'A BRILLIANT SERVICE':'GREAT IDEAS ARE COOKING'}</div>${['screen','host'].includes(role)&&ui.publicCook?publicCookPopup(ui.publicCook):''}</section>`;}
function joinDetails(large=false){if(large)return `<section class="join-details host-join-details"><div class="host-join-copy"><span class="eyebrow">SCAN TO JOIN</span><h2>Scan. Join. Get cooking.</h2><p>One phone per team. Scan the QR code, choose an available team, and stay on the student screen.</p></div><img class="join-qr" src="${API_BASE}/${esc(pin)}/qr.svg" alt="Scan this QR code to join room ${esc(pin)}"><span class="join-or">OR</span><div class="join-pin-row"><strong>${esc(pin)}</strong>${btn('Copy join link ↗','copy-join','button green small')}</div><p class="join-help">Open <b>${esc(`${location.origin}/?battle=7&student=1`)}</b> and enter the PIN.</p></section>`;return `<section class="join-details"><div><span class="eyebrow">GRAB ONE PHONE PER TEAM</span><h2>Scan. Join. Get cooking.</h2><p>Or open <b>${esc(`${location.origin}/?battle=7&student=1`)}</b> and enter the PIN.</p><div class="join-pin-row"><strong>${esc(pin)}</strong>${mode==='host'?btn('Copy join link ↗','copy-join','button green small'):''}</div></div><img class="join-qr" src="${API_BASE}/${esc(pin)}/qr.svg" alt="Scan this QR code to join room ${esc(pin)}"></section>`;}
function projector(){return `${appHeader('screen')}<main id="main" class="projector-main"><div class="projector-heading"><h1>${esc(state.roomName)}</h1><span>${phaseLabel()}</span></div>${progress()}<div class="projector-board">${kitchenScene('screen')}<aside class="projector-side">${state.phase==='lobby'?joinDetails():state.phase==='finished'?finalStage('screen'):state.phase==='rush'?`<section class="projector-cooking"><span class="eyebrow">ROUND ${state.questionNumber} · COOK OR SAVE</span><h2>${rushActive()?'Yes, chef!':'Pans down!'}</h2><p>${rushActive()?'Combine three ingredients on your team’s phone, or save them for another round.':'Your ingredients are saved. Your teacher will start the next round.'}</p><small>⭐ First global recipe discovery earns +1</small></section>`:questionStage('screen')}</aside></div><section class="projector-leaderboard">${leaderboard()}</section>${recentCooks()}</main>`;}
function publicCookPopup(c){const d=c.dish || {};return `<div class="public-cook-popup ${d.type==='basic'?'basic-dish':''}" role="status"><span class="eyebrow">${esc(c.teamName)} · ${c.discoveryBonus?'FIRST DISCOVERY!':'ORDER UP!'}</span><span class="popup-dish">${esc(d.emoji || '🍽️')}</span><h2>${esc(d.name)}</h2><strong>${c.starsEarned>0?`+${c.starsEarned} ★`:d.type==='steal'?'🕵️ Sneaky Snack power':d.type==='steal-star'?'⭐ Steal 1 Star power':'0 ★'}</strong><p>${d.type==='basic'?'A tasty start! Secret recipes can earn even more.':c.discoveryBonus?'Includes the +1 discovery bonus.':d.type==='steal-star'?'No stars for cooking it — the sabotage power is saved.':'Fresh from the kitchen.'}</p></div>`;}
const seenCookIds=new Set();let cookQueue=[],cookQueueTimer=null,cookHistoryInitialized=false;
function queuePublicCooks(next){if(!['screen','host'].includes(mode))return;const cooks=next.latestCooks || [];if(!cookHistoryInitialized){cooks.forEach(c=>seenCookIds.add(c.id));cookHistoryInitialized=true;return;}cooks.filter(c=>!seenCookIds.has(c.id)).sort((a,b)=>a.at-b.at).forEach(c=>{seenCookIds.add(c.id);cookQueue.push(c);});showNextPublicCook();}
function showNextPublicCook(){if(ui.publicCook||!cookQueue.length)return;ui.publicCook=cookQueue.shift();render();cookQueueTimer=setTimeout(()=>{ui.publicCook=null;render();cookQueueTimer=setTimeout(()=>{cookQueueTimer=null;showNextPublicCook();},350);},3600);}
const seenStarEventIds=new Set();let starEventHistoryInitialized=false;
function queueStarTheftEvents(next){if(!['screen','host'].includes(mode))return;const events=(next.events||[]).filter(e=>e.type==='star-theft');if(!starEventHistoryInitialized){events.forEach(e=>seenStarEventIds.add(e.id));starEventHistoryInitialized=true;return;}const fresh=events.filter(e=>!seenStarEventIds.has(e.id)).sort((a,b)=>a.at-b.at);fresh.forEach(e=>seenStarEventIds.add(e.id));const latest=fresh[fresh.length-1];if(latest)setNotice(`⭐ ${latest.text}`);}
function finalStage(){const winners=state.teams.filter(t=>state.winners?.includes(t.id)),names=winners.map(t=>t.name).join(' & ');return `<section class="final-stage stage"><div class="confetti" aria-hidden="true">✦ <span>✧</span> ✦ <span>✧</span> ✦</div><span class="eyebrow">THAT’S A WRAP, CHEFS</span><span class="trophy" aria-hidden="true">🏆</span><h2>${winners.length>1?'A delicious tie.':'The stars of the kitchen.'}</h2><h3>${esc(names || 'Every chef who gave it a go')}</h3><p>${winners[0]?`${winners[0].stars} stars. `:''}Great teamwork. Bold choices. Brilliant cooking.</p><span class="final-caption">Ranked by stars, then accepted answers. Equal on both? Share the crown.</span></section>`;}
function joinView(){if(state.phase!=='lobby')return `<main id="main" class="center-state">${brand()}<span class="big-symbol">🍳</span><h1>This kitchen has already started.</h1><p>Reopen the browser your team used to join, or ask your teacher about the next game.</p>${btn('Enter a new student PIN','student-entry','button green')}</main>`;return `<div class="site-shell narrow"><header class="site-header">${brand(true)}${connection()}</header><main id="main" class="join-room"><div class="join-room-heading"><span class="eyebrow">ROOM ${esc(pin)} · ${esc(state.roomName)}</span><h1>Pick your<br><em>kitchen crew.</em></h1><p>One device per team. Your place stays saved here.</p></div><form id="team-form"><div class="team-slots">${Array.from({length:state.teamCount},(_,i)=>i+1).map(n=>{const taken=state.takenSlots?.includes(n),t=state.teams.find(t=>t.slot===n);return `<button class="team-slot team-color-${(n-1)%5} ${ui.slot===n?'selected':''}" type="button" data-action="select-team" data-slot="${n}" aria-pressed="${ui.slot===n}"${disabled(taken||ui.loading)}><span>${icon(n)}</span><b>${taken?esc(t?.name || `Team ${n}`):`Team ${n}`}</b><small>${taken?'Already taken':ui.slot===n?'Your team ✓':'Grab this spot'}</small></button>`;}).join('')}</div><div class="field"><label for="team-name">Give your team a name</label><input id="team-name" name="teamName" maxlength="24" placeholder="The Saucy Squad" value="${esc(ui.teamName)}" required autocomplete="off"></div><button class="button green wide" type="submit"${disabled(!ui.slot||ui.loading)}>${ui.loading?'Saving your place…':'Aprons on. Let’s go! →'}</button>${btn('← Use a different PIN','student-entry','text-button')}</form></main></div>`;}
function pupil(){return `${appHeader('team')}<main id="main" class="phone-shell"><div class="phone-kicker"><span>${icon(state.me.slot)} TEAM ${esc(state.me.name)}</span><span>${state.phase==='lobby'?'Ready, chef':`Q${state.questionNumber}/20`}</span></div><nav class="phone-tabs" aria-label="Team sections">${[['play','Question','✍️'],['cook','Cook','🍳'],['pantry','Pantry','🧺'],['recipes','Recipes','📖']].map(([tab,label,emoji])=>btn(`${emoji} ${label}${tab==='pantry'?` <span>${totalStock(state.me.inventory)}</span>`:tab==='recipes'&&state.me.recipes?.length?` <span>${state.me.recipes.length}</span>`:''}`,`tab-${tab}`,`phone-tab ${ui.tab===tab?'active':''}`,`aria-current="${ui.tab===tab?'page':'false'}"`)).join('')}</nav>${ui.tab==='recipes'?recipeBook():ui.tab==='pantry'?pantryView():ui.tab==='cook'?cookingView():pupilPlay()}${ui.tab==='play'&&cookingActive()?cookReady():''}<div class="phone-footer"><span class="room-chip">ROOM <b>${esc(pin)}</b></span><span>Your place is saved on this device.</span></div></main>`;}
function pupilPlay(){switch(state.phase){case'lobby':return `<section class="phone-welcome"><div class="welcome-image"><img src="./assets/kitchen-hero.png" alt="A cheerful chef preparing for service"></div><div class="welcome-copy"><span class="eyebrow">YOU’RE ON THE TEAM</span><h1>Looking sharp,<br><em>chef.</em></h1><p>Your teacher will start the game soon. Talk to your team and get ready.</p><div class="ready-status"><i class="live-dot"></i> Connected & ready</div></div></section><div class="phone-rules"><p><span>✍️</span> Each accepted answer earns 2 random ingredients</p><p><span>🍳</span> Cook with exactly 3 ingredients</p><p><span>★</span> Earn stars or discover a saved sabotage power</p></div>`;case'question':return pupilQuestion();case'reveal':return `${pupilSubmission()}${questionStage('team')}<div class="phone-wait"><span class="spinner"></span> Waiting for the next question. You can cook on the Cook tab.</div>`;case'rush':return `${pupilSubmission()}${questionStage('team')}<p class="phone-wait">Your teacher will continue the lesson. Cooking stays open.</p>`;case'finished':return `${finalStage('team')}<div class="personal-total"><span>Your team earned</span><strong>${state.me.stars} ★</strong><p>${state.me.recipes?.length || 0} recipes discovered. What a service!</p></div>${leaderboard()}<p class="phone-wait">Stay here for your results. Scan the next QR code when your teacher is ready.</p>`;default:return'';}}
function pupilSubmission(){const sub=state.me.submission;if(!sub)return'';return `<section class="submission-status ${esc(sub.status)}"><span class="submission-icon">${sub.status==='accepted'?'✓':sub.status==='rejected'?'↻':'✓'}</span><div><h2>${sub.status==='accepted'?'Nicely done, chef!':sub.status==='rejected'?'One to learn from.':'Order received!'}</h2>${sub.status==='accepted'?`<div class="reward-pair" aria-label="Two ingredients added to your pantry">${rewardPair(sub)}</div><p>Two ingredients added to your pantry.</p>`:`<p>${sub.unanswered?'No answer was submitted, so your teacher marked this one wrong.':sub.status==='rejected'?'Your teacher didn’t accept this answer. Watch the reveal and try the next one.':'Your answer is saved. Waiting for your teacher to review it.'}</p>`}</div></section>`;}
function pupilQuestion(){const q=state.question;if(!q)return'';const sub=state.me.submission;return `<section class="phone-question">${answerCountdown('phone')}<div class="question-topline"><span class="eyebrow">${esc(FORMAT[q.format])}</span><span class="question-index">${String(state.questionNumber).padStart(2,'0')}</span></div><p class="question-instruction">${esc(q.instruction)}</p><h1 class="question-prompt">${prompt(q)}</h1>${sub?`${pupilSubmission()}${sub.unanswered?'':`<div class="your-answer"><span class="eyebrow">YOUR TEAM’S ANSWER</span><p>${esc(sub.answer)}</p></div>`}`:answerInput(q)}<p class="answer-note">${answerTimeUp()?'Time is up. Wait for your teacher to review the answers.':'Think together. Submit one answer for your team.'}</p></section>`;}
function answerInput(q){const locked=answerTimeUp();return `<form id="answer-form" class="${locked?'answer-locked':''}">${locked?'<div class="time-up-note">⏱ Time is up — answers are locked.</div>':''}${q.format==='typed_correction'?`<label class="input-label" for="team-answer">Replacement for the bold words</label><textarea id="team-answer" name="answer" rows="3" maxlength="500" placeholder="Type the replacement only…" autocorrect="off" spellcheck="false"${disabled(ui.busy||locked)}>${esc(ui.answer)}</textarea>`:q.format==='multiple_choice'?`<div class="answer-options">${(q.options || []).map((o,i)=>`<button type="button" data-action="option" data-option="${esc(o.id)}" class="answer-option ${ui.answer===o.text?'selected':''}" aria-pressed="${ui.answer===o.text}"${disabled(ui.busy||locked)}><span>${String.fromCharCode(65+i)}</span><b>${esc(o.text)}</b><i>${ui.answer===o.text?'✓':''}</i></button>`).join('')}</div>`:`<div class="sentence-builder"><span class="input-label">Tap words to build your sentence</span><div class="built-sentence" aria-label="Your sentence">${ui.wordOrder.length?ui.wordOrder.map((id,i)=>{const t=q.tokens.find(t=>t.id===id);return `<button type="button" class="word-chip selected" data-action="remove-word" data-index="${i}" aria-label="Remove ${esc(t?.text)}"${disabled(locked)}>${esc(t?.text)} <span>×</span></button>`;}).join(''):'<span class="sentence-placeholder">Your sentence starts here…</span>'}</div><div class="available-words">${(q.tokens || []).map(t=>`<button type="button" data-action="add-word" data-token="${esc(t.id)}" class="word-chip"${disabled(ui.busy||locked||ui.wordOrder.includes(t.id))}>${esc(t.text)}</button>`).join('')}</div>${btn('Start again','clear-words','text-button',disabled(locked))}</div>`}<button type="submit" class="button green wide submit-answer"${disabled(ui.busy || locked || !answerValue(q).trim())}>${locked?'Time is up':ui.busy?'Sending your answer…':'Submit team answer →'}</button></form>`;}
function answerValue(q){return q?.format==='sentence_rebuild'?ui.wordOrder.map(id=>q.tokens.find(t=>t.id===id)?.text || '').join(' '):ui.answer;}
function pantryView(){const inv=state.me.inventory;return `<section class="pantry-heading"><span class="eyebrow">YOUR SECRET INGREDIENTS</span><h1>The pantry.</h1><p>${totalStock(inv)} ingredients. Endless possibilities.</p></section>${ingredientGrid(false)}<div class="pantry-note"><span>💡</span><p>Cook whenever you have three ingredients during the game. Repeats are allowed if you own them. The order doesn’t matter.</p></div>${powersView(cookingActive())}${cookingActive()?btn('Open my cooking station →','tab-cook','button green wide'):''}`;}
function cookReady(){const ready=totalStock(state.me.inventory)>=3;return `<section class="cook-ready"><div><b>${ready?'🍳 Your pan is ready':'🧺 Keep collecting'}</b><p>${ready?'Cook for stars now, or save ingredients for a secret recipe.':`${totalStock(state.me.inventory)} / 3 ingredients. Each accepted answer adds two.`}</p></div>${btn(ready?'Cook now →':'See my pan','tab-cook','button green small')}</section>`;}
function ingredientGrid(interactive){return `<div class="ingredient-grid ${interactive?'interactive':''}">${Object.entries(INGREDIENTS).map(([name,emoji])=>{const owned=Number(state.me.inventory?.[name] || 0),selected=ui.selected.filter(x=>x===name).length,available=owned-selected;return interactive?`<article class="ingredient-card ${!owned?'empty':''} ${selected?'chosen':''}"><button type="button" data-action="add-ingredient" data-ingredient="${name}" class="ingredient-add" aria-label="Add ${name}; ${available} available"${disabled(ui.busy||available<1||ui.selected.length>=3||!rushActive())}><span class="ingredient-emoji">${emoji}</span><b>${name}</b><small>${available} available</small><span class="ingredient-plus">+</span></button>${selected?btn('−','remove-ingredient','ingredient-minus',`data-ingredient="${name}" aria-label="Remove one ${name}"${disabled(ui.busy)}`):''}${selected?`<span class="selected-quantity">${selected} in pan</span>`:''}</article>`:`<article class="ingredient-card pantry-item ${!owned?'empty':''}"><span class="ingredient-emoji">${emoji}</span><b>${name}</b><strong>×${owned}</strong></article>`;}).join('')}</div>`;}
function cookingView(){const active=cookingActive();return `<div class="phone-rush-heading"><div><span class="eyebrow">YOUR TEAM’S COOKING STATION</span><h1>${active?'Let’s cook.':'Pans down!'}</h1></div></div>${!active?`<div class="service-ended"><span>🛎️</span><h2>${state.phase==='lobby'?'Waiting for the start.':'Service complete.'}</h2><p>${state.phase==='lobby'?'Your teacher will open the game soon.':'Your final results stay on the Question tab.'}</p></div>${btn('Back to the team','tab-play','button secondary wide')}`:`<p class="cook-anytime-note">Cook anytime with exactly 3 ingredients. Every ordinary dish earns at least 1 ★. Secret recipes can earn more or unlock a saved sabotage power.</p><section class="cooking-station"><div class="pan-heading"><h2>What’s in your pan?</h2><span>${ui.selected.length}/3</span></div><div class="pan-slots">${Array.from({length:3},(_,i)=>`<button type="button" class="pan-slot ${ui.selected[i]?'filled':''}" data-action="remove-slot" data-index="${i}" aria-label="${ui.selected[i]?`Remove ${ui.selected[i]}`:`Empty ingredient slot ${i+1}`}"${disabled(!ui.selected[i]||ui.busy)}><span>${ui.selected[i]?INGREDIENTS[ui.selected[i]]:'+'}</span><small>${esc(ui.selected[i] || 'Ingredient')}</small>${ui.selected[i]?'<i>×</i>':''}</button>`).join('')}</div><button type="button" class="button coral wide cook-button" data-action="cook"${disabled(ui.selected.length!==3||ui.busy)}>${ui.busy&&pending?.type==='pupil:cook'?'<span class="pan-bounce">🍳</span> Cooking…':'🍳 Cook this combination'}</button><p class="tiny muted">Every cook uses all 3 ingredients. Earn stars now, or save ingredients for a secret recipe.</p></section><div class="pantry-label"><h2>Pick your ingredients</h2><span>${totalStock(state.me.inventory)} in your pantry</span></div>${ingredientGrid(true)}${totalStock(state.me.inventory)<3?`<p class="empty-pantry">You need at least 3 ingredients to cook. Keep answering to grow your pantry.</p>`:''}${powersView(true)}`}`;}

function powersView(interactive){const powers=state.me.powers || [];if(!powers.length)return'';const snacks=powers.filter(p=>p.type==='steal'),stars=powers.filter(p=>p.type==='steal-star');return `${snacks.length?`<section class="powers-card"><div class="powers-heading"><span>🕵️</span><div><span class="eyebrow">A LITTLE KITCHEN MISCHIEF</span><h2>Sneaky Snack <span>×${snacks.length}</span></h2></div></div><p>Use one power to take one random ingredient from another team. Their stars stay safe.</p>${interactive?btn('Choose a rival →','choose-rival','button green wide',disabled(ui.busy||!rushActive())):'<small>Ready to use anytime during the game.</small>'}</section>`:''}${stars.length?`<section class="powers-card star-snatcher"><div class="powers-heading"><span>⭐</span><div><span class="eyebrow">STAR SNATCHER TART</span><h2>Steal 1 Star <span>×${stars.length}</span></h2></div></div><p>Transfer exactly one chef star from an eligible rival to your team. The power stays saved if you cancel or the target becomes unavailable.</p>${interactive?btn('Steal 1 Star →','choose-star-rival','button coral wide',disabled(ui.busy||!rushActive())):'<small>Saved for any question while the game is open.</small>'}</section>`:''}`;}
function recipeBook(){const recipes=state.me.recipes || [];return `<section class="pantry-heading"><span class="eyebrow">YOUR TEAM’S DISCOVERIES</span><h1>The recipe book.</h1><p>${recipes.length?'A little less mystery. A little more mastery.':'Every great chef starts with a blank page.'}</p></section>${recipes.length?`<div class="recipe-list">${recipes.map(r=>`<article class="recipe-card"><span class="recipe-emoji">${esc(r.emoji || '🍽️')}</span><div><h2>${esc(r.name)}</h2><div class="recipe-ingredients">${(r.ingredients || []).map(i=>`<span>${INGREDIENTS[i] || ''} ${esc(i)}</span>`).join('')}</div><span class="recipe-value">${r.type==='steal'?'🕵️ Makes one stored ingredient-steal power':r.type==='steal-star'?'⭐ Makes one stored Steal 1 Star power · 0 ★':`${r.stars} ★ every time you cook it`}</span></div></article>`).join('')}</div>`:`<div class="empty-recipes"><span>📖</span><h2>Something delicious<br>is waiting to be discovered.</h2><p>Any ordinary combination earns at least 1 star. Discover a secret recipe to save it here, just for your team. Basic dishes do not earn discovery bonuses.</p><div class="mystery-recipe">? <span>+</span> ? <span>+</span> ? <span>=</span> ✦</div></div>`}`;}
function modal(){if(ui.review&&mode==='host')return answerReviewModal();if(!ui.modal)return'';if(ui.modal.type==='confirm-close')return `<div class="modal-backdrop"><section class="modal-card compact-modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><span class="big-symbol">🛎️</span><h2 id="modal-title">Close this kitchen?</h2><p>This ends the game. Teams keep their final results on their phones.</p><div class="modal-actions">${btn('Keep playing','close-modal','button secondary')}${btn('End room','confirm-close','button coral',disabled(ui.busy))}</div></section></div>`;
 if(ui.modal.type==='rival')return `<div class="modal-backdrop"><section class="modal-card rival-modal" role="dialog" aria-modal="true" aria-labelledby="modal-title">${btn('×','close-modal','modal-close icon-button','aria-label="Close rival selection"')}<span class="big-symbol">🕵️</span><span class="eyebrow">SNEAKY SNACK</span><h2 id="modal-title">Who’s got the goods?</h2><p>Take one random ingredient. Empty pantries are off limits.</p><div class="rival-list">${state.teams.filter(t=>t.id!==state.me.id).map(t=>btn(`<span>${icon(t.slot)}</span><span><b>${esc(t.name)}</b><small>${t.canBeStolenFrom===false&&t.inventoryCount>0?'Already targeted this round':`${t.inventoryCount} ingredients`}</small></span><span>→</span>`,'steal','rival-button',`data-team="${esc(t.id)}"${disabled(ui.busy||!rushActive()||t.inventoryCount<1||t.canBeStolenFrom===false)}`)).join('')}</div><small class="muted">Each team can be targeted only once per question. If the target is unavailable, your power is kept.</small></section></div>`;
 if(ui.modal.type==='star-rival')return `<div class="modal-backdrop"><section class="modal-card rival-modal star-rival-modal" role="dialog" aria-modal="true" aria-labelledby="modal-title">${btn('×','close-modal','modal-close icon-button','aria-label="Cancel star target selection"')}<span class="big-symbol">⭐</span><span class="eyebrow">STAR SNATCHER TART</span><h2 id="modal-title">Steal 1 Star</h2><p>Choose a rival with at least one chef star.</p><div class="rival-list">${state.teams.filter(t=>t.id!==state.me.id).map(t=>{const reason=t.stars<1?'No stars to steal':t.canLoseStar===false?'Already lost a star this question':`${t.stars} star${t.stars===1?'':'s'} available`;return btn(`<span>${icon(t.slot)}</span><span><b>${esc(t.name)}</b><small>${reason}</small></span><span>→</span>`,'steal-star','rival-button',`data-team="${esc(t.id)}"${disabled(ui.busy||!rushActive()||t.stars<1||t.canLoseStar===false)}`);}).join('')}</div><div class="modal-actions">${btn('Cancel — save power','close-modal','button secondary')}</div><small class="muted">A team can lose only one star to this power per question. If a target becomes unavailable, your power stays saved.</small></section></div>`;
 return ''; }
function dishNotice(){const c=ui.dishNotice;if(!c)return'';const d=c.dish||{};return `<aside class="dish-notice ${d.type==='basic'?'basic-dish':''}" role="status" aria-live="polite">${btn('×','close-dish','icon-button','aria-label="Dismiss cooking result"')}<span class="dish-notice-icon">${esc(d.emoji||'🍽️')}</span><div><b>${esc(d.name)}</b><p>${c.starsEarned>0?`+${c.starsEarned} ★${c.discoveryBonus?' · First discovery +1 included':''}`:d.type==='steal'?'Sneaky Snack power ready':d.type==='steal-star'?'Steal 1 Star power saved · 0 ★':`${Number(c.starsEarned)||0} ★ from this dish`}</p></div></aside>`;}

async function api(path,body,auth=token){const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),10000);try{const response=await fetch(path,{method:body?'POST':'GET',headers:{...(body?{'Content-Type':'application/json'}:{}),...(auth?{Authorization:`Bearer ${auth}`}:{})},body:body?JSON.stringify(body):undefined,signal:controller.signal,cache:'no-store'});let data;try{data=await response.json();}catch{throw new Error('The kitchen server returned an unexpected response. Please try again.');}if(!response.ok){const error=new Error(data.error || 'That action could not be completed.');error.status=response.status;error.code=data.code;throw error;}return data;}finally{clearTimeout(timeout);}}
function applyState(next,force=false){if(!next||String(next.pin)!==pin)return false;if((mode==='join'&&next.role==='host')||(mode==='screen'&&next.role&&next.role!=='public')||(mode==='host'&&next.role&&next.role!=='host'&&token)){state=null;ui.error='This session belongs to another role. Reopen your team link.';render();return false;}if(state&&String(state.pin)===String(next.pin)&&Number.isFinite(state.version)&&Number.isFinite(next.version)&&next.version<state.version)return false;const oldPhase=state?.phase,oldQuestion=state?.question?.id;state=next;queuePublicCooks(next);queueStarTheftEvents(next);if(mode==='host'&&next.role==='host'&&window.parent!==window)window.parent.postMessage({type:'crazy-kitchen:status',pin,phase:next.phase,onlineCount:next.teams.filter(t=>t.online).length},location.origin);if(next.serverTime)clockOffset=Number(next.serverTime)-Date.now();if(oldQuestion!==next.question?.id){ui.answer='';ui.wordOrder=[];ui.questionId=next.question?.id;ui.review=false;}if(oldPhase!==next.phase){if(!['question','reveal','rush'].includes(next.phase)){ui.selected=[];ui.tab='play';ui.modal=null;}if(['rival','star-rival'].includes(ui.modal?.type)&&!cookingActive())ui.modal=null;if(oldPhase)announce(phaseLabel());}if(state.me){const used={};ui.selected=ui.selected.filter(n=>{used[n]=(used[n]||0)+1;return used[n]<=(state.me.inventory?.[n]||0);});}const signature=JSON.stringify({...next,serverTime:0});if(force||signature!==ui.signature){ui.signature=signature;render();}}
function joinRecoveryView(){return `<div class="site-shell narrow"><header class="site-header">${brand(true)}${connection()}</header><main id="main" class="center-state"><span class="loading-pan" aria-hidden="true">🍳</span><h1>Saving your team’s place…</h1><p>We’re confirming ${esc(pendingJoin.name)} in room ${esc(pendingJoin.pin)}. If your teacher has already started, we’ll reconnect you to the same team.</p><p class="tiny muted">Keep this page open. Your original team choice is saved while we reconnect.</p>${btn('Retry connection','retry-join','button green',disabled(!!joinInFlight&&joinInFlight.generation===routeGeneration))}${btn('Use another student PIN','student-entry','text-button')}</main></div>`;}
async function beginJoin(){
  if(mode!=='join'||token||pendingJoin||ui.loading)return;
  let clientId=storage.get('crazy-kitchen:clientId');if(!clientId){clientId=uid();storage.set('crazy-kitchen:clientId',clientId);}
  pendingJoin={pin,clientId,teamSlot:ui.slot,name:ui.teamName.trim()};
  storage.set(pendingJoinKey(),JSON.stringify(pendingJoin));ui.loading=true;ui.error='';joinRetryDelay=3000;render();
  await deliverPendingJoin();
}
async function deliverPendingJoin(){
  if(mode!=='join'||token||!pendingJoin||(joinInFlight&&joinInFlight.generation===routeGeneration))return;
  const attempt={generation:routeGeneration,pin,join:pendingJoin};joinInFlight=attempt;joinLastAttempt=Date.now();
  try{
    const data=await api(`${API_BASE}/${encodeURIComponent(attempt.pin)}/join`,{clientId:attempt.join.clientId,teamSlot:attempt.join.teamSlot,name:attempt.join.name},'');
    if(attempt.generation!==routeGeneration||pendingJoin!==attempt.join)return;
    if(typeof data.teamToken!=='string'||!data.teamToken)throw new Error('The team confirmation was incomplete. Reconnecting safely.');
    storage.set(`crazy-kitchen:team:${attempt.pin}`,data.teamToken);storage.remove(pendingJoinKey(attempt.pin));
    token=data.teamToken;pendingJoin=null;ui.loading=false;ui.online=true;ui.error='';joinRetryDelay=3000;
    routeGeneration++;state=null;ui.signature='';render();await loadState();
  }catch(error){
    if(attempt.generation!==routeGeneration||pendingJoin!==attempt.join)return;
    if(error.status>=400&&error.status<500&&error.status!==429){
      storage.remove(pendingJoinKey(attempt.pin));pendingJoin=null;ui.loading=false;ui.slot=0;ui.error=error.message;
      await loadState();render();
    }else{ui.online=false;joinRetryDelay=Math.min(30000,joinRetryDelay*1.6);render();}
  }finally{if(joinInFlight===attempt){joinInFlight=null;if(mode==='join'&&pendingJoin)render();}}
}
async function loadState(){
  if(['home','student'].includes(mode)||!/^\d{5}$/.test(pin)||(pollInFlight&&pollInFlight.generation===routeGeneration))return;
  const request={generation:routeGeneration,pin,mode,token};pollInFlight=request;
  try{
    const data=await api(`${API_BASE}/${encodeURIComponent(request.pin)}/state`,undefined,request.mode==='screen'?'':request.token);
    if(request.generation!==routeGeneration)return;
    const reconnect=!ui.online;ui.online=true;applyState(data.state || data,reconnect);if(reconnect)announce('Reconnected to your kitchen.');
  }catch(error){
    if(request.generation!==routeGeneration)return;
    if(error.status){if(!state){ui.error=error.message;render();}else if(error.status===401){ui.error='Your saved kitchen session could not be verified. Refresh the page to reconnect.';render();}}
    else{if(ui.online){ui.online=false;render();}if(!state&&!pendingJoin){ui.error='We couldn’t reach your kitchen. Check your connection or room PIN.';render();}}
  }finally{if(pollInFlight===request)pollInFlight=null;}
}
async function sendAction(type,extra={}){if(pending||ui.busy)return;if(!canSendAction(type)){ui.error='This action is not available to your role.';render();return;}pending={type,requestId:uid(),...extra,...(['host:start-countdown','host:reveal','host:advance','host:end-rush','pupil:cook','pupil:steal','pupil:steal-star'].includes(type)?{questionId:state?.question?.id,expectedPhase:state?.phase}:{})};storage.set(pendingKey(),JSON.stringify(pending));ui.busy=true;ui.error='';render();await deliverPending();}
function canSendAction(type){return Boolean(token&&((type.startsWith('host:')&&mode==='host'&&state?.role==='host')||(type.startsWith('pupil:')&&mode==='join'&&state?.role==='team')));}
async function deliverPending(){
  if(pending&&!canSendAction(pending.type)){if(!state)return;pending=null;ui.busy=false;storage.remove(pendingKey());return;}
  if(!pending||(actionInFlight&&actionInFlight.generation===routeGeneration))return;
  const request={generation:routeGeneration,pin,token,action:pending};actionInFlight=request;lastAttempt=Date.now();
  try{
    const data=await api(`${API_BASE}/${encodeURIComponent(request.pin)}/action`,request.action,request.token);
    if(request.generation!==routeGeneration||request.action!==pending)return;
    const action=request.action;pending=null;ui.busy=false;retryDelay=3000;storage.remove(pendingKey());ui.online=true;applyState(data.state,true);
    if(action.type==='pupil:cook'){ui.selected=[];let cook=data.result?.cook || (data.result?.dish?data.result:null);if(!cook)cook=[...(state.latestCooks || [])].reverse().find(c=>c.teamId===state.me?.id);if(cook){ui.dishNotice=cook;setTimeout(()=>{if(ui.dishNotice?.id===cook.id){ui.dishNotice=null;render();}},5000);}render();}
    if(action.type==='pupil:steal'){ui.modal=null;setNotice(data.result?.ingredient?`${INGREDIENTS[data.result.ingredient] || '🥣'} One ${data.result.ingredient} added to your pantry!`:'Sneaky Snack used. Your pantry is up to date.');render();}
    if(action.type==='pupil:steal-star'){ui.modal=null;setNotice(`⭐ 1 star taken from ${data.result?.targetTeamName || 'the rival team'}!`);render();}
    if(action.type==='host:close')ui.modal=null;render();
  }catch(error){
    if(request.generation!==routeGeneration||request.action!==pending)return;
    if(error.status>=400&&error.status<500&&error.status!==429){pending=null;ui.busy=false;storage.remove(pendingKey());ui.error=error.message;if(request.action.type==='pupil:steal')ui.modal=null;await loadState();render();}
    else{ui.online=false;ui.busy=true;retryDelay=Math.min(30000,retryDelay*1.6);render();}
  }finally{if(actionInFlight===request)actionInFlight=null;}
}
function navigate(nextMode,nextPin){
  const sticky=studentRoute();
  if(nextMode==='join'){nextPin=/^\d{5}$/.test(String(nextPin))?String(nextPin):'';rememberStudent(nextPin);if(!nextPin)nextMode='student';}
  else if(nextMode==='student'){nextPin='';rememberStudent('');}
  else if(sticky){nextMode=sticky.room?'join':'student';nextPin=sticky.room;}
  routeGeneration++;mode=nextMode;pin=nextPin;token=['screen','home','student'].includes(mode)?'':storage.get(credentialKey())||'';
  if(mode==='join'||mode==='student')replaceRoute(mode==='join'?`?join=${pin}`:'?student=1');else syncParentRoute();
  state=null;ui.error='';ui.signature='';ui.slot=0;ui.review=false;ui.modal=null;ui.dishNotice=null;ui.publicCook=null;seenCookIds.clear();cookQueue=[];cookHistoryInitialized=false;seenStarEventIds.clear();starEventHistoryInitialized=false;if(cookQueueTimer)clearTimeout(cookQueueTimer);pending=null;pendingJoin=null;ui.busy=false;ui.loading=false;joinRetryDelay=3000;
  try{pending=JSON.parse(storage.get(pendingKey())||'null');ui.busy=!!pending;}catch{}
  if(mode==='join'){if(token)storage.remove(pendingJoinKey());else{pendingJoin=readPendingJoin(pin);if(pendingJoin){ui.slot=pendingJoin.teamSlot;ui.teamName=pendingJoin.name;ui.loading=true;}}}
  render();if(pendingJoin)deliverPendingJoin();loadState().then(()=>{if(pending&&token)deliverPending();});
}
function readRoute(){const params=new URLSearchParams(location.search);if(params.has('join'))return navigate('join',params.getAll('join').length===1?params.get('join')||'':'');if(params.has('student'))return navigate('student','');const sticky=studentRoute();if(sticky)return navigate(sticky.room?'join':'student',sticky.room);for(const key of ['host','screen'])if(params.has(key)){const code=params.get(key)||'';if(params.getAll(key).length===1&&/^\d{5}$/.test(code)){if(key==='host'&&!storage.get(`crazy-kitchen:host:${code}`))return navigate('student','');return navigate(key,code);}return navigate('student','');}navigate('home','');if(params.has('teacher')||!params.has('screen'))openKitchen();}
async function openKitchen(fresh=false){
 if(studentRoute()||ui.loading)return;
 const saved=session.get('crazy-kitchen:last-host');
 if(!fresh&&/^\d{5}$/.test(saved||'')&&storage.get(`crazy-kitchen:host:${saved}`)){replaceRoute(`?host=${saved}`);navigate('host',saved);return;}
 ui.loading=true;ui.error='';render();const generation=routeGeneration;
 try{const data=await api(API_BASE,{teamCount:10,roomName:'Crazy Kitchen'},'');if(generation!==routeGeneration||studentRoute())return;if(!/^\d{5}$/.test(String(data.pin))||!/^[a-f0-9]{64}$/.test(data.hostToken||''))throw new Error('The teacher room could not be confirmed.');storage.set(`crazy-kitchen:host:${data.pin}`,data.hostToken);session.set('crazy-kitchen:last-host',String(data.pin));ui.loading=false;replaceRoute(`?host=${data.pin}`);navigate('host',String(data.pin));}
 catch(error){if(generation===routeGeneration){ui.loading=false;ui.error=error.message;render();}}
}

async function copy(text,label){try{await navigator.clipboard.writeText(text);setNotice(label);render();}catch{ui.modal=null;ui.error=`Couldn’t copy automatically. ${label.includes('PIN')?'Room PIN: ':''}${text}`;render();}}
app.addEventListener('input',e=>{if(e.target.id==='team-answer'){ui.answer=e.target.value;const b=$('.submit-answer');if(b)b.disabled=ui.busy||!ui.answer.trim();}if(e.target.id==='team-name')ui.teamName=e.target.value;if(e.target.form?.id==='create-form')ui.form[e.target.name]=e.target.value;});
app.addEventListener('change',e=>{if(e.target.id==='lobby-team-count')sendAction('host:configure',{teamCount:Number(e.target.value)});});
 app.addEventListener('submit',async e=>{e.preventDefault();const id=e.target.id;if(id==='pin-form'){const code=String(new FormData(e.target).get('pin')||'').trim();if(!/^\d{5}$/.test(code)){ui.error='Enter the five-digit PIN your teacher shared.';render();return;}navigate('join',code);return;}if(id==='answer-form'&&mode==='join'&&state?.me){if(answerTimeUp()){ui.error='Time is up. Wait for your teacher to review the answers.';render();return;}const answer=answerValue(state.question).trim();if(answer)await sendAction('pupil:submit',{questionId:state.question.id,answer});return;}if(id==='team-form')await beginJoin();});
 app.addEventListener('click',async e=>{if(e.target.classList?.contains('review-backdrop')&&!ui.busy){ui.review=false;render();return;}const target=e.target.closest('[data-action]');if(!target||target.disabled)return;const action=target.dataset.action;switch(action){case'open-kitchen':openKitchen();return;case'new-kitchen':if(mode==='host'&&state?.role==='host'){navigate('home','');openKitchen(true);}return;case'replace-kitchen':if(mode==='host'&&!studentRoute()){navigate('home','');openKitchen(true);}return;case'student-entry':if(['join','student'].includes(mode))navigate('student','');return;case'close-dish':ui.dishNotice=null;break;case'clear-error':ui.error='';break;case'clear-notice':ui.notice='';break;case'reload':ui.error='';loadState();break;case'retry':deliverPending();return;case'retry-join':deliverPendingJoin();return;case'copy-join':copy(`${state?.joinUrl || shareUrl('join')}`,'Join link copied. Share it with your teams.');return;case'copy-pin':copy(pin,'Room PIN copied.');return;case'fullscreen':try{if(document.fullscreenElement){await document.exitFullscreen();}else{await document.documentElement.requestFullscreen();}}catch{setNotice('Use your browser’s fullscreen control to fill the screen.');}break;case'toggle-review':ui.review=!ui.review;break;case'start':await sendAction('host:start');return;case'start-countdown':await sendAction('host:start-countdown');return;case'reveal':await sendAction('host:reveal');return;case'advance':await sendAction('host:advance');return;case'end-rush':await sendAction('host:end-rush');return;case'accept':case'reject':await sendAction('host:review',{teamId:target.dataset.team,questionId:state.question.id,decision:action==='accept'?'accepted':'rejected'});return;case'end-confirm':ui.modal={type:'confirm-close'};break;case'confirm-close':await sendAction('host:close');return;case'close-modal':ui.modal=null;break;case'select-team':ui.slot=Number(target.dataset.slot);break;case'option':ui.answer=state.question.options.find(o=>String(o.id)===target.dataset.option)?.text || '';break;case'add-word':if(!ui.wordOrder.includes(target.dataset.token))ui.wordOrder.push(target.dataset.token);break;case'remove-word':ui.wordOrder.splice(Number(target.dataset.index),1);break;case'clear-words':ui.wordOrder=[];break;case'add-ingredient':if(rushActive()&&ui.selected.length<3&&ui.selected.filter(n=>n===target.dataset.ingredient).length<(state.me.inventory[target.dataset.ingredient]||0))ui.selected.push(target.dataset.ingredient);break;case'remove-ingredient':{const index=ui.selected.lastIndexOf(target.dataset.ingredient);if(index>=0)ui.selected.splice(index,1);break;}case'remove-slot':ui.selected.splice(Number(target.dataset.index),1);break;case'cook':if(ui.selected.length===3&&rushActive())await sendAction('pupil:cook',{ingredients:[...ui.selected]});return;case'choose-rival':ui.modal={type:'rival'};break;case'choose-star-rival':ui.modal={type:'star-rival'};break;case'steal':{const power=state.me.powers?.find(p=>p.type==='steal');if(power)await sendAction('pupil:steal',{targetTeamId:target.dataset.team,powerId:power.id});return;}case'steal-star':{const power=state.me.powers?.find(p=>p.type==='steal-star');if(power)await sendAction('pupil:steal-star',{targetTeamId:target.dataset.team,powerId:power.id});return;}default:if(action.startsWith('tab-')){ui.tab=action.slice(4);window.scrollTo({top:0,behavior:'smooth'});}}render();if(ui.modal||ui.review){$('.modal-card button')?.focus({preventScroll:true});}});
document.addEventListener('keydown',e=>{if(!ui.modal&&!ui.review)return;if(e.key==='Escape'&&!ui.busy){ui.modal=null;ui.review=false;render();return;}if(e.key==='Tab'){const buttons=[...document.querySelectorAll('.modal-card button:not(:disabled),.modal-card a[href]')];if(!buttons.length)return;const first=buttons[0],last=buttons[buttons.length-1];if(e.shiftKey&&document.activeElement===first){last.focus();e.preventDefault();}else if(!e.shiftKey&&document.activeElement===last){first.focus();e.preventDefault();}}});
 function updateTimers(){const seconds=remaining();document.querySelectorAll('[data-timer]').forEach(el=>{el.textContent=String(seconds).padStart(2,'0');el.closest('.phone-timer,.rush-clock')?.classList.toggle('urgent',seconds<=10);});const answerSeconds=answerRemaining();document.querySelectorAll('[data-answer-timer]').forEach(el=>{el.textContent=String(answerSeconds??0).padStart(2,'0');const timer=el.closest('.answer-countdown');timer?.classList.toggle('urgent',answerSeconds!==null&&answerSeconds<=3);timer?.classList.toggle('ended',answerSeconds===0);});if(state?.phase==='question'&&state.answerCountdownEndsAt&&answerSeconds===0&&!ui.answerTimerExpired){ui.answerTimerExpired=true;render();loadState();}if(state?.phase!=='question'||!state?.answerCountdownEndsAt||answerSeconds>0)ui.answerTimerExpired=false;if(state?.phase==='rush'&&!state.rushEnded&&seconds===0&&!ui.timerExpired){ui.timerExpired=true;render();loadState();}if(state?.phase!=='rush'||seconds>0)ui.timerExpired=false;}
window.addEventListener('popstate',readRoute);window.addEventListener('pageshow',e=>{if(e.persisted)readRoute();});window.addEventListener('online',()=>{ui.online=true;loadState();deliverPending();deliverPendingJoin();});window.addEventListener('offline',()=>{ui.online=false;render();});document.addEventListener('visibilitychange',()=>{if(!document.hidden)loadState();});
setInterval(()=>{if(!['home','student'].includes(mode)){loadState();if(pending&&token&&Date.now()-lastAttempt>retryDelay)deliverPending();if(pendingJoin&&Date.now()-joinLastAttempt>joinRetryDelay)deliverPendingJoin();}},1000);setInterval(updateTimers,250);
